{
  "id": "p_000",
  "summary": "Diseño REST minimalista en JSON para gestionar tareas con CRUD, códigos HTTP, ejemplos y formato de error estándar.",
  "approach": "Modelar el recurso task con campos mínimos y tipos explícitos; exponer rutas /tasks y /tasks/{id} usando GET, POST, PATCH y DELETE; definir respuestas exitosas y de error con códigos 200, 201, 204, 400, 404 y 422; incluir ejemplos de request/response y un objeto de error común.",
  "tradeoffs": [
    "PATCH en lugar de PUT simplifica actualizaciones parciales, pero exige definir una semántica de mezcla de campos.",
    "No incluir autenticación mantiene el alcance mínimo, pero hace el diseño no apto para producción sin extensiones.",
    "GET /tasks sin paginación simplifica la API, pero puede requerir cambios si el volumen de tareas crece."
  ],
  "evidence": [
    "El recurso task define id UUID, title string, description string, status enum, due_date date nullable, created_at date-time y updated_at date-time.",
    "Los endpoints CRUD usan métodos HTTP estándar y respuestas con códigos 200, 201, 204, 400, 404 y 422.",
    "El formato de error estándar incluye code, message y details."
  ],
  "artifacts": [],
  "task": {
    "fields": {
      "id": {
        "type": "string",
        "format": "uuid",
        "description": "Identificador único generado por el servidor."
      },
      "title": {
        "type": "string",
        "description": "Título de la tarea."
      },
      "description": {
        "type": "string",
        "description": "Descripción opcional de la tarea."
      },
      "status": {
        "type": "string",
        "enum": ["pending", "in_progress", "done"],
        "description": "Estado de la tarea."
      },
      "due_date": {
        "type": "string",
        "format": "date",
        "nullable": true,
        "description": "Fecha límite opcional."
      },
      "created_at": {
        "type": "string",
        "format": "date-time",
        "description": "Fecha y hora de creación."
      },
      "updated_at": {
        "type": "string",
        "format": "date-time",
        "description": "Fecha y hora de última actualización."
      }
    },
    "required": ["id", "title", "status", "created_at", "updated_at"]
  },
  "endpoints": [
    {
      "method": "GET",
      "path": "/tasks",
      "purpose": "Listar todas las tareas.",
      "request_body": null,
      "responses": {
        "200": {
          "description": "Colección de tareas.",
          "body": {
            "type": "array",
            "items": "task"
          }
        },
        "400": {
          "description": "Solicitud inválida.",
          "body": "error"
        }
      }
    },
    {
      "method": "GET",
      "path": "/tasks/{id}",
      "purpose": "Obtener una tarea por id.",
      "path_parameters": {
        "id": {
          "type": "string",
          "format": "uuid"
        }
      },
      "request_body": null,
      "responses": {
        "200": {
          "description": "Tarea encontrada.",
          "body": "task"
        },
        "400": {
          "description": "id inválido.",
          "body": "error"
        },
        "404": {
          "description": "Tarea no encontrada.",
          "body": "error"
        }
      }
    },
    {
      "method": "POST",
      "path": "/tasks",
      "purpose": "Crear una tarea.",
      "request_body": {
        "content_type": "application/json",
        "schema": {
          "title": {
            "type": "string",
            "required": true
          },
          "description": {
            "type": "string",
            "required": false
          },
          "status": {
            "type": "string",
            "enum": ["pending", "in_progress", "done"],
            "required": false,
            "default": "pending"
          },
          "due_date": {
            "type": "string",
            "format": "date",
            "required": false,
            "nullable": true
          }
        }
      },
      "responses": {
        "201": {
          "description": "Tarea creada.",
          "body": "task"
        },
        "400": {
          "description": "JSON inválido o campos mal formados.",
          "body": "error"
        },
        "422": {
          "description": "Validación semántica fallida.",
          "body": "error"
        }
      }
    },
    {
      "method": "PATCH",
      "path": "/tasks/{id}",
      "purpose": "Actualizar parcialmente una tarea.",
      "path_parameters": {
        "id": {
          "type": "string",
          "format": "uuid"
        }
      },
      "request_body": {
        "content_type": "application/json",
        "schema": {
          "title": {
            "type": "string",
            "required": false
          },
          "description": {
            "type": "string",
            "required": false
          },
          "status": {
            "type": "string",
            "enum": ["pending", "in_progress", "done"],
            "required": false
          },
          "due_date": {
            "type": "string",
            "format": "date",
            "required": false,
            "nullable": true
          }
        }
      },
      "responses": {
        "200": {
          "description": "Tarea actualizada.",
          "body": "task"
        },
        "400": {
          "description": "id inválido o JSON inválido.",
          "body": "error"
        },
        "404": {
          "description": "Tarea no encontrada.",
          "body": "error"
        },
        "422": {
          "description": "Validación semántica fallida.",
          "body": "error"
        }
      }
    },
    {
      "method": "DELETE",
      "path": "/tasks/{id}",
      "purpose": "Eliminar una tarea.",
      "path_parameters": {
        "id": {
          "type": "string",
          "format": "uuid"
        }
      },
      "request_body": null,
      "responses": {
        "204": {
          "description": "Tarea eliminada.",
          "body": null
        },
        "400": {
          "description": "id inválido.",
          "body": "error"
        },
        "404": {
          "description": "Tarea no encontrada.",
          "body": "error"
        }
      }
    }
  ],
  "http_status_codes": {
    "200": "OK para lecturas y actualizaciones exitosas.",
    "201": "Created para creación exitosa.",
    "204": "No Content para eliminación exitosa.",
    "400": "Bad Request para solicitudes mal formadas.",
    "404": "Not Found cuando el recurso no existe.",
    "422": "Unprocessable Entity para errores de validación semántica."
  },
  "error_format": {
    "content_type": "application/json",
    "fields": {
      "code": {
        "type": "string",
        "description": "Código de error estable y legible por máquina."
      },
      "message": {
        "type": "string",
        "description": "Mensaje legible para humanos."
      },
      "details": {
        "type": "array",
        "items": {
          "type": "object"
        },
        "description": "Detalles estructurados opcionales del error."
      }
    },
    "required": ["code", "message", "details"]
  },
  "examples": {
    "create_task": {
      "request": {
        "method": "POST",
        "path": "/tasks",
        "body": {
          "title": "Preparar informe",
          "description": "Incluir métricas mensuales.",
          "status": "pending",
          "due_date": "2026-07-01"
        }
      },
      "response": {
        "status": 201,
        "body": {
          "id": "9c1b2f8e-4d5a-4f6b-9c0d-1a2b3c4d5e6f",
          "title": "Preparar informe",
          "description": "Incluir métricas mensuales.",
          "status": "pending",
          "due_date": "2026-07-01",
          "created_at": "2026-06-20T10:00:00Z",
          "updated_at": "2026-06-20T10:00:00Z"
        }
      }
    },
    "read_task": {
      "request": {
        "method": "GET",
        "path": "/tasks/9c1b2f8e-4d5a-4f6b-9c0d-1a2b3c4d5e6f",
        "body": null
      },
      "response": {
        "status": 200,
        "body": {
          "id": "9c1b2f8e-4d5a-4f6b-9c0d-1a2b3c4d5e6f",
          "title": "Preparar informe",
          "description": "Incluir métricas mensuales.",
          "status": "pending",
          "due_date": "2026-07-01",
          "created_at": "2026-06-20T10:00:00Z",
          "updated_at": "2026-06-20T10:00:00Z"
        }
      }
    },
    "update_task": {
      "request": {
        "method": "PATCH",
        "path": "/tasks/9c1b2f8e-4d5a-4f6b-9c0d-1a2b3c4d5e6f",
        "body": {
          "status": "in_progress"
        }
      },
      "response": {
        "status": 200,
        "body": {
          "id": "9c1b2f8e-4d5a-4f6b-9c0d-1a2b3c4d5e6f",
          "title": "Preparar informe",
          "description": "Incluir métricas mensuales.",
          "status": "in_progress",
          "due_date": "2026-07-01",
          "created_at": "2026-06-20T10:00:00Z",
          "updated_at": "2026-06-21T09:30:00Z"
        }
      }
    },
    "delete_task": {
      "request": {
        "method": "DELETE",
        "path": "/tasks/9c1b2f8e-4d5a-4f6b-9c0d-1a2b3c4d5e6f",
        "body": null
      },
      "response": {
        "status": 204,
        "body": null
      }
    },
    "error_not_found": {
      "response": {
        "status": 404,
        "body": {
          "code": "TASK_NOT_FOUND",
          "message": "La tarea no existe.",
          "details": [
            {
              "field": "id",
              "issue": "not_found"
            }
          ]
        }
      }
    },
    "error_validation": {
      "response": {
        "status": 422,
        "body": {
          "code": "VALIDATION_ERROR",
          "message": "El estado no es válido.",
          "details": [
            {
              "field": "status",
              "issue": "must be one of: pending, in_progress, done"
            }
          ]
        }
      }
    }
  }
}
